    public function findByrechercheagent($grade,$anciennetedge,$anciennetegrade=0,$regle=0,$poids=0,$ancienneteagent=0){
        
        $qb = $this->getEntityManager()->createQueryBuilder()
      ->select("a as agent,CONCAT_WS(' ',a.nom,a.prenoms,a.nomJeuneFille) as matricule,".$regle.' as regle,'.$poids.' as poids')
                //->addSelect("CURRENT_TIMESTAMP(), a.datePriseServiceDge,TimestampDiff('YEAR', a.datePriseServiceDge, CURRENT_TIMESTAMP())")
              ->from('AgentBundle:Agent', 'a')
                 ->innerjoin('AgentBundle:Emploi', 'e', Join::WITH, 'a.Emploi = e.id')
                ->leftjoin('AgentBundle:Grade', 'g', Join::WITH, 'e.Grade = g.id')
              ->where('1=1')
              ;
      if($grade>0)
      {
          $qb=$qb->andWhere('e.Grade = :grade')
                  ->setParameter('grade', $grade);
      }
     
      if($anciennetedge>0)
      {
          $qb=$qb->andWhere(" TimestampDiff('YEAR', a.datePriseServiceDge, CURRENT_TIMESTAMP())>=:anciennetedge")
                  ->setParameter('anciennetedge', $anciennetedge);
      }
      if($anciennetegrade>0)
      {
          $qb=$qb->andWhere(" TimestampDiff('YEAR', a.datePriseServicePromotion, CURRENT_TIMESTAMP()) >=:anciennetegrade")
                  ->setParameter('anciennetegrade', $anciennetegrade);
      }
      if($ancienneteagent>0)
      {
          $qb=$qb->andWhere(" TimestampDiff('YEAR', a.datePremierService, CURRENT_TIMESTAMP())>=:ancienneteagent")
                  ->setParameter('ancienneteagent', $ancienneteagent);
      }
      
      //dump($qb->getQuery()->getResult());die;
              return $qb->getQuery()->getResult();
              
      
    }
     
    public function creationcompteusers() {
        $qb = $this->createQueryBuilder('a')
                ->Leftjoin('UsersBundle:Users', 'u', Join::WITH, 'a.matricule = u.username')
                ->where('u.username is null');

        return $qb->getQuery()->getResult();
    }

