    public function afficherAgent($position = null) {
        $qb = $this->createQueryBuilder('a');
        //->where('a.position is null')
        if ($position) {
            $qb->where('a.position = :Position')
                    ->setParameter('Position', $position);
        }
        $qb->orderBy('a.nom')
        ;
        return $qb->getQuery()->getResult();
    }
    
    public function AfficherAgentExp(){
    
        $qb = $this->createQueryBuilder('a')
           // ->select('a')
              ->leftJoin('EcompetenceBundle:Experience', 'exp', Join::WITH,'a.id = exp.agent') 
              ->leftJoin('AgentBundle:Emploi', 'e', Join::WITH,'a.Emploi = e.id')
              ->leftJoin('AgentBundle:Fonction', 'fonct', Join::WITH,'exp.fonction = fonct.id')       
              ->leftJoin('EcompetenceBundle:Formation', 'f', Join::WITH,'f.agent = a.id')
              ->leftJoin('EcompetenceBundle:Agent_Langue', 'al', Join::WITH,'al.agent = a.id')
              ->leftJoin('EcompetenceBundle:Langue', 'l', Join::WITH,'al.langue = l.id')
              ->leftJoin('EcompetenceBundle:Agentcompetence', 'ac', Join::WITH,'ac.agent = a.id')
              ->leftJoin('EcompetenceBundle:Domaine', 'd', Join::WITH,'ac.competence = d.id');
        $qb->where('a.matricule is not null');
        $qb->orderBy('a.nom');
   
    return $qb->getQuery()->getResult();
  }
  public function findProfileByParametres($data,$data1=null){
    
 
    $qb = $this->createQueryBuilder('a')
           
            ->leftJoin('EcompetenceBundle:Experience', 'exp', Join::WITH,'a.id = exp.agent') 
            ->leftJoin('AgentBundle:Emploi', 'e', Join::WITH,'a.Emploi = e.id')
            //->leftJoin('AgentBundle:Fonction', 'fonct', Join::WITH,'exp.fonction = fonct.id')       
            ->leftJoin('EcompetenceBundle:Formation', 'f', Join::WITH,'f.agent = a.id')
            ->leftJoin('EcompetenceBundle:Agent_Langue', 'al', Join::WITH,'al.agent = a.id')
            ->leftJoin('EcompetenceBundle:Langue', 'l', Join::WITH,'al.langue = l.id')
            ->leftJoin('EcompetenceBundle:Agentcompetence', 'ac', Join::WITH,'ac.agent = a.id')
            ->leftJoin('EcompetenceBundle:Domaine', 'd', Join::WITH,'ac.competence = d.id')
            ->leftJoin('AgentBundle:Grade', 'g', Join::WITH, 'e.Grade = g.id');
            $qb->where('a.matricule is not null');
            if ($data['poste'] != ''){
                    $qb->andWhere('a.Fonction = :poste')
                    ->setParameter('poste',$data['poste']);
            }
            if ($data['emploi'] != ''){
                    $qb->andWhere('e.id = :emploi')
                    ->setParameter('emploi',$data['emploi']);
            }
            if ($data['diplome'] != ''){
                    $qb->andWhere('f.diplome = :diplome')
                    ->setParameter('diplome',$data['diplome']);
            }

              if ($data['specialite'] != ''){
                    $qb->andWhere('f.specialite = :specialite')
                    ->setParameter('specialite',$data['specialite']);
            }
             if ($data['option'] != ''){
                    $qb->andWhere('f.option = :option')
                    ->setParameter('option',$data['option']);
            }

             if ($data1!= null){
                    $qb->andWhere('d.id in (:domaine)')
                    ->setParameter('domaine',$data1);
                    
            }
            if ($data['anneeexpdge'] != ''){
                    $format='P'.$data['anneeexpdge'].'Y';
                    $datePriseDge =new \DateTime('now');
                    $datePriseDge ->sub(new DateInterval($format));
                    $datePriseDge ->format('Y-m-d') ;
                    $qb->andWhere('a.datePriseServiceDge <= :datePriseDge')
                    ->setParameter('datePriseDge',$datePriseDge);
             }
             
              if ($data['anneetotexp'] != ''){
                    $format='P'.$data['anneetotexp'].'Y';
                    $datePrise =new \DateTime('now');
                    $datePrise ->sub(new DateInterval($format));
                    $datePrise ->format('Y-m-d') ;
                    $qb->andWhere('exp.dateDebExp <= :datePrise')
                    ->setParameter('datePrise',$datePrise);
             }

             if (!empty($data['direction'])) {
             $qb->andWhere('a.Direction = :direction')
             ->setParameter('direction', $data['direction']);
            }

            if (!empty($data['serviceRattache'])) {
            $qb->leftJoin('a.code_sc', 'sc')
            ->andWhere('sc.id = :service')
            ->setParameter('service', $data['serviceRattache']);
            }

            if (!empty($data['sousDirection'])) {
            $qb->andWhere('a.code_sd = :sd')
            ->setParameter('sd', $data['sousDirection']);
          }

        // Grade (via Emploi → déjà joint avec e)
        if (!empty($data['grade'])) {
           $qb->andWhere('g.id = :grade')
           ->setParameter('grade', $data['grade']);
           }

       // Type agent (champ simple)
       if (!empty($data['Type'])) {
            $qb->andWhere('a.Type = :typeAgent')
            ->setParameter('typeAgent', $data['Type']);
          }
     
            $qb->orderBy('a.nom')
           
                  
          /*  ->where("a.matAgent=:matriculemodif")
            ->setparameter("matriculemodif",$matricule)*/;
    
               // ;
             
        return $qb->getQuery()->getResult();
    }
 

    public function afficherAgentMe($user) {
        $idForMe = $user->getAgent()->getFonction()->getId();
        //dump()
        $code_sd = $user->getAgent()->getCodeSd();
        $code_sc = $user->getAgent()->getCodeSc();
        $code_dc = $user->getAgent()->getDirection();

        $qb = $this->createQueryBuilder('a');
        if ($idForMe == 3) {
            //chef de section
            $qb->orWhere('a.code_sd = :sd and a.Direction = :direction')
                    ->setParameter('sd', $code_sd)
                    ->setParameter('direction', $code_dc);
            ;
        }
        if ($idForMe == 4) {
            //chef de service
            $qb->orWhere('a.code_sc = :sc and a.Direction = :direction')
                    ->setParameter('sc', $code_sc)
                    ->setParameter('direction', $code_dc);
            ;
        }

        if ($idForMe == 5) {
            //chef de service Rattaché
            $qb->orWhere('a.Direction = :direction')
                    ->setParameter('direction', $code_dc);
        }

        if ($idForMe == 6) {
            //Sous Directeur
            $qb->orWhere('a.code_sd = :sd and a.Direction = :direction')
                    ->setParameter('sd', $code_sd)
                    ->setParameter('direction', $code_dc);
            ;
        }

        if ($idForMe == 7) {
            //Directeur
            $qb->orWhere('a.Direction = :direction')
                    ->setParameter('direction', $code_dc);
        }
        $qb->orderBy('a.nom');
        return $qb->getQuery()->getResult();
    }

    public function findAgentByParametres($data) {
        //dump($data.length); die;
        $qb = $this->createQueryBuilder('a');
        $qb->where('a.matricule is not null');

        if ($data['direction'] != '') {
            $qb->andWhere('a.Direction = :direction')
                    ->setParameter('direction', $data['direction']);
        }
        if ($data['emploi'] != '') {
            $qb->andWhere('a.Emploi = :emploi')
                    ->setParameter('emploi', $data['emploi']);
        }
        if ($data['grade'] != '') {
            $qb->join('a.Emploi', 'e')
                    ->addSelect('e')
                    ->andWhere('e.Grade = :grade')
                    ->setParameter('grade', $data['grade']);
        }
        if ($data['sexe'] != '') {
            $qb->andWhere('a.Sexe = :sexe')
                    ->setParameter('sexe', $data['sexe']);
        }
        if ($data['situation'] != '') {
            $qb->andWhere('a.situationMatri = :situation')
                    ->setParameter('situation', $data['situation']);
        }
        if ($data['type'] != '') {
            $qb->andWhere('a.Type = :type')
                    ->setParameter('type', $data['type']);
        }
        $qb->andWhere('a.position is null or a.position = 0')->orderBy('a.nom');
        // ;
        return $qb->getQuery()->getResult();
    }

    public function findSuperieurSD($roles, $Direction) {
        $qb = $this->createQueryBuilder('a')
                ->join('a.users', 'u')
                ->addSelect('u')
                ->where("u.roles LIKE :roles")
                ->andWhere("a.Direction = :Direction")
                ->setParameter("Direction", $Direction)
                ->setParameter("roles", '%"' . $roles . '"%')
                ->setMaxResults(1);
        return $qb->getQuery()->getOneOrNullResult();
    }

