    public function getsup($champ, $value, $fonction) {

        if ($fonction != 10) {
            if ($champ == 'DG0001') {
                $qb = $this->createQueryBuilder('a')
                        ->where('a.Fonction =:Fonction And a.code_dg =:codedg')
                        ->setParameter('Fonction', 10)
                        ->setParameter('codedg', $champ);
            } else {
                $qb = $this->createQueryBuilder('a')
                        ->where('a.Fonction >:Fonction')
                        ->andWhere('a.' . $value . '=:valeur')
                        ->andWhere('a.Fonction >:only and a.Fonction <>:dg')
                        ->setParameter('only', $fonction)
                        ->setParameter('Fonction', 2)
                        ->setParameter('dg', 10)
                        ->setParameter('valeur', $champ);
            }
        } else {
            $qb = $this->createQueryBuilder('a')
                    ->where('a.Fonction =:Fonction And a.code_dg =:codedg')
                    ->setParameter('Fonction', 10)
                    ->setParameter('codedg', $champ);
        }
        //dump($qb->getQuery()); die;
        return $qb->getQuery()->getResult();
    }

    public function find_sup($service) {
        $long = strlen($service);
        if ($long == 7) {
            $vv = "a.matricule = '" . $service . "' ";
        } else {

            switch (substr($service, 0, 2)) {
                case 'DG': $fonct = '(10,9)';
                    $col = 'code_dg';
                    $filt = ' And a.code_dg is not null';
                    break;
                case 'DC': $fonct = '(10,9,8,7,6,5)';
                    $col = 'code_dc';
                    $filt = ' And a.code_sd is null';
                    break;
                case 'SD': $fonct = '(10,9,8,7,6,5, 4,3)';
                    $col = 'code_sd';
                    $filt = ' And a.code_sc is null';
                    break;
                case 'SC': $fonct = '(10,9,8,7,6,5, 4,3)';
                    $col = 'code_sc';
                    $filt = ' And a.code_sc is  not null';
                    break;
            }
            $vv = 'a.' . $col . " = '" . $service . "' And f.id In " . $fonct . $filt;
        }

        $qb = $this->createQueryBuilder('a')
                ->innerJoin('a.Fonction', 'f')
                ->where($vv);
        //dump($qb->getQuery()->getResult());die;
        return $qb->getQuery()->getResult();
    }

