    public function find_sup_agent($matricule, $courrier) {
        $qb = $this->createQueryBuilder('a')
                //->select('a.matricule as m, a.code_dg, a.code_dc, a.code_sd, a.code_sc, a.Fonction ')
                ->where('a.matricule =:matricule')
                ->setParameter('matricule', $matricule);
        $ex = $qb->getQuery()->getResult();

        if (!empty($ex[0]->getCodeSc())) {
            $err = 1;
        } elseif (!empty($ex[0]->getCodeSd())) {
            $err = 1;
        } elseif (!empty($ex[0]->getCodeDc())) {
            $err = 1;
        } else {
            $err = 0;
            $qb1 = $this->getEntityManager()->createQueryBuilder()
                    ->from('EdiligenceBundle:Timputations', 'c')
                    ->innerjoin('EdiligenceBundle:TimputDir', 't', Join::WITH, 'c.id = t.imputation and c.coordinateur = t.serviceImput')
                    ->innerjoin('AgentBundle:Agent', 'e', Join::WITH, 't.matriculeimpute = e.matricule')
                    ->select('c.coordinateur, c.nbrePers, e')
                    ->Where("c.serviceImput=:serviceImput")
                    ->andWhere("c.nbrePers >= 1")
                    ->andWhere("c.courrier=:courrier")
                    ->setParameter('serviceImput', $ex[0]->getCodeDg()->getCodeDg())
                    ->setParameter('courrier', $courrier);
            $ex1 = $qb1->getQuery()->getResult();
            //dump($ex1[0]);  dump($ex1[0]['nbrePers']);die;
        }

        if ($err == 1) {
            $result = 1;
        } else {
            if ($ex1[0]['nbrePers'] == 1) {
                $result = 1;
            } else {
                $result = $ex1[0];
            }
        }
        return $result;
    }

    public function comboDest() {
        $qb = $this->createQueryBuilder('a')
                //->select("concat(' ', a.nom, a.prenoms) as p ")
                ->innerjoin('AgentBundle:DirectionGenerale', 'dg', Join::WITH, 'a.code_dg = dg.codeDg')
                ->Leftjoin('AgentBundle:Direction', 'dc', Join::WITH, 'a.code_dc = dc.code_dc')
                ->where('a.Fonction In (10,9)')
                ->orderBy('a.Fonction', 'DESC');
        return $qb;
    }

