                ->where($critere);
        //->andWhere("a.Fonction In(:fonction)")
        //->setParameter("fonction", array(1,2));
        return $qb->getQuery()->getResult();
    }

    public function findsupBy($critere, $tri, $cascade, $fonction) {
        $qb = $this->createQueryBuilder('a')
                        ->where($critere)
                        ->orderBy($tri)
                        ->setMaxResults(1)
                        ->getQuery()->getOneOrNullResult();

        if ($qb != null) {
            $rec = $qb;
        } else {
            $fixe = '';
            $cascade = explode(',', substr($cascade, 7, strlen($cascade)));
            $qb1 = $this->createQueryBuilder('a')
                    ->where($fonction);

            for ($i = 0; $i < count($cascade); $i++) {
                switch (substr($cascade[$i], 0, 2)) {
                    case 'SC': $fixe = "a.code_sc = '" . $cascade[$i] . "' ";
                        break;
                    case 'SD': $fixe = "a.code_sd = '" . $cascade[$i] . "' ";
                        break;
                    case 'DC': $fixe = "a.code_dc = '" . $cascade[$i] . "' ";
                        break;
                    case 'DG': $fixe = "a.code_dg = '" . $cascade[$i] . "' ";
                        break;
                }
                $qb1 = $qb1->andWhere($fixe)
                                ->orderBy('a.Fonction', 'DESC')
                                ->setMaxResults(1)
                                ->getQuery()->getOneOrNullResult();
                //dump($qb1->getQuery());die;
                if ($qb1 != null) {
                    $rec = $qb1;
                    break;
                }
            }
        }

        return $rec;
    }

    function designerliste($agent = null) {
        $qb = $this->createQueryBuilder('a');
        if ($agent != "null" && $agent && $agent != null && $agent->getMatricule()) {
            $qb = $qb->where('a.matricule <>:mat')
                    ->setParameter('mat', $agent->getMatricule());
        }
        $qb = $qb->orderBy('a.nom, a.prenoms, a.nomJeuneFille', 'ASC');

        return $qb;
    }

    function findgrh() {
        $qb = $this->createQueryBuilder('a')
                ->innerjoin('UsersBundle:Users', 'u', Join::WITH, 'a.id = u.agent')
                ->where("u.roles like :role ")
                ->setParameter('role', '%ROLE_RESPO_SRHMG%')
        ;
        return $qb->getQuery()->getOneOrNullResult();
    }

